import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS Hammer (Day 2) - librbd: Shared Flag, Object Map","description":"","frontmatter":{"title":"CDS Hammer (Day 2) - librbd: Shared Flag, Object Map","date":"2014-10-30T00:00:00.000Z","updated":"2014-10-31T00:00:00.000Z","tags":["Ceph","librbd","独占锁","对象映射","共享标志"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_2_-_librbd_-_Shared_Flag_Object_Map.md","filePath":"posts/2014/CDS_Hammer_Day_2_-_librbd_-_Shared_Flag_Object_Map.md","lastUpdated":1780459816000}'),_={name:"posts/2014/CDS_Hammer_Day_2_-_librbd_-_Shared_Flag_Object_Map.md"};function e(o,l,s,p,n,d){return i(),a("div",null,[...l[0]||(l[0]=[r("<p>会议纪要</p><p><strong>会议时间</strong>： 2023年XX月XX日</p><p><strong>参会人员</strong>： Maya, Josh, Jason, Foreign</p><p><strong>会议主题</strong>： 讨论Ceph RBD（Rados Block Device）的独占锁特性和对象映射功能</p><p><strong>关键细节</strong>：</p><ul><li><p><strong>独占锁特性</strong>：</p><ul><li>RBD新增独占锁特性，默认情况下，所有图像除非标记为共享，否则都将应用此新功能位，表示它支持独占锁定。</li><li>当独占锁定功能位启用时，任何对图像的写操作或可变操作都将导致RBD尝试获取对图像的独占权锁。</li><li>通过watch notify系统，客户端可以请求获取锁，并从当前锁持有者那里获取锁或通知释放锁。</li><li>维护操作（如快照、扁平化、调整大小）也可以通过watch notify系统请求当前独占锁持有者执行。</li></ul></li><li><p><strong>对象映射</strong>：</p><ul><li>对象映射通过Rados中的类方法进行操作，用于加载、更改映射中对象的状态等。</li><li>映射状态为三态：不存在、可能存在、待删除。</li><li>当客户端请求对RBD图像中给定对象的写操作时，如果该对象当前未标记为不存在，则客户端将更新对象映射并将其提交到磁盘，然后继续进行radius操作。</li><li>通过检查对象映射，可以优化对磁盘的任何读请求。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>独占锁特性和对象映射功能的实现细节。</li><li>对象映射中“可能存在”状态的使用场景和问题。</li><li>对象映射的存储和更新效率。</li><li>与老版本客户端的兼容性问题。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>确认独占锁特性和对象映射功能的实现细节。</li><li>优化对象映射的存储和更新效率。</li><li>考虑与老版本客户端的兼容性问题，并寻找解决方案。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续完善独占锁特性和对象映射功能。</li><li>优化对象映射的存储和更新效率。</li><li>研究与老版本客户端的兼容性问题，并寻找解决方案。</li></ul><p><strong>其他</strong>：</p><ul><li>讨论了关于扩展RBD头部以支持不同类型的权限位，例如读写权限位。</li><li>讨论了使用Delta字节而不是完整映射来更新对象映射的可能性。</li></ul>",14)])])}const u=t(_,[["render",e]]);export{c as __pageData,u as default};
